  ssoCallback: {
    parameters: {
      query?: never;
      header?: never;
      path: {
        /** @description The registered provider id (string slug, e.g. `corp-okta`). */
        provider: string;
      };
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json": components["schemas"]["SsoCallbackRequest"];
      };
    };
    responses: {
      /** @description SSO sign-in succeeded (session cookie set), OR — for the consumer `google` provider when the verified email matches an existing PASSWORD account not yet linked — a `link_required` challenge (NO cookie set, NO mutation), OR — when the KV state record carried a `link_user_id` (minted by /v1/auth/link/google/start) — a `linked` envelope confirming the authenticated user just connected Google from the account page (the session is UNCHANGED; no new cookie). The response is a discriminated union of three shapes: the signed-in branch is a plain `User`; the link-required branch carries `status: "link_required"` + a single-use `challenge_id` + the matched `email`; the account-link branch carries `status: "linked"` + `return_to` + the updated `methods`. The client distinguishes account-link (go to `return_to`, toast "Google connected") from sign-in (a plain `User`, go to `/products`) on the presence of `status: "linked"`. */
      200: {
        headers: {
          "Set-Cookie"?: string;
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["SsoCallbackResult"];
        };
      };
      /** @description State missing / consumed / malformed / tampered, or userinfo returned no `email`, or — for the `google` provider — the `email_verified` claim was absent or false, or malformed body — same generic body for ALL branches. No session is issued; the KV state entry IS consumed when present, to prevent replay. */
      400: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["SsoError"];
        };
      };
      /** @description Link-mode CSRF guard. The KV state carried a `link_user_id` but the request presented no valid session, or a session whose user id does NOT equal `link_user_id`. The link is bound to the session that initiated it; a mismatched/absent session is rejected and NOTHING is changed. */
      403: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["SsoError"];
        };
      };
      /** @description Link-mode conflict. Either the Google `email` does not match the authenticated account's email (`email_mismatch`), or the Google `sub` is already linked to a DIFFERENT account (`identity_conflict`), or the account is already linked to a different Google identity. Nothing is changed. Only reachable when the state carried a `link_user_id`. */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["LinkAccountError"];
        };
      };
      /** @description Provider's token endpoint or userinfo endpoint returned an error or was unreachable. Same generic body for BOTH branches. The KV state entry IS consumed; no users row is upserted; no session is issued. */
      502: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["SsoError"];
        };
      };
    };
  };
